tail -30 optimized.log && python - <<'PY'
import numpy as np,json
from collections import Counter
lines=open('optimized.xyz').readlines()[2:];els=[l.split()[0] for l in lines];p=np.array([[float(v) for v in l.split()[1:4]] for l in lines]);mp=json.load(open('mapping.json'));m=mp['map']
print('Formula',Counter(els))
for i,j in [(0,1),(0,m['Si1']),(0,m['N']),(0,m['Si2']),(0,m['Otf']),(m['N'],m['NH']),(m['P'],m['PH']),(m['NH'],m['ONH']),(m['PH'],m['Otf'])]:print('distance',i,j,np.linalg.norm(p[i]-p[j]))
print('Covalent bond lengths outliers:')
radii={'H':.31,'C':.76,'N':.71,'O':.66,'Si':1.11,'P':1.07,'S':1.05,'F':.57,'Rh':1.42}
bs={tuple(sorted((i,j))) for i,j,b in mp['bonds']}
for i,j,b in mp['bonds']:
 d=np.linalg.norm(p[i]-p[j]);rs=radii[els[i]]+radii[els[j]]
 if d>1.4*rs or d<.7*rs:print(i,j,els[i],els[j],b,round(d,3))
print('Possible unexpected covalent contacts:')
for i in range(len(els)):
 for j in range(i):
  if tuple(sorted((i,j))) in bs:continue
  d=np.linalg.norm(p[i]-p[j]);rs=radii[els[i]]+radii[els[j]]
  if d<1.15*rs:print(i,j,els[i],els[j],round(d,3))
